# solution: drop-in replacement for _retry_after
import math
from datetime import datetime, timezone
from email.utils import parsedate_to_datetime

# MAX_RETRY_AFTER_SECONDS = 24 * 3600 already exists in dispatcher.py

def _retry_after(resp: httpx.Response, now: datetime | None = None) -> float | None:
    raw = resp.headers.get("retry-after")
    if raw is None:
        return None
    try:
        delay = float(raw)
    except ValueError:
        try:
            when = parsedate_to_datetime(raw)
        except (TypeError, ValueError):
            return None
        if when.tzinfo is None:
            when = when.replace(tzinfo=timezone.utc)
        delay = (when - (now or datetime.now(timezone.utc))).total_seconds()
    if not math.isfinite(delay):
        return None
    return min(max(delay, 0.0), MAX_RETRY_AFTER_SECONDS)

# tests (illustrative)
def test_retry_after_forms():
    now = datetime(2026, 11, 16, 12, 0, tzinfo=timezone.utc)
    r = lambda v: httpx.Response(429, headers={"retry-after": v})
    assert _retry_after(r("120"), now) == 120
    assert _retry_after(r("Mon, 16 Nov 2026 12:02:00 GMT"), now) == 120
    assert _retry_after(r("Mon, 16 Nov 2026 11:00:00 GMT"), now) == 0
    assert _retry_after(r("99999999"), now) == 24 * 3600
    assert _retry_after(r("inf"), now) is None and _retry_after(r("soon"), now) is None

// solution: receiver.ts
import express from "express";
import crypto from "node:crypto";

const SECRETS = (process.env.WEBHOOK_SECRETS ?? "").split(",").filter(Boolean);
const TOLERANCE_S = 300;
const seen = new Set<string>();              // demo only; use a DB unique constraint in production

function sign(secret: string, id: string, ts: string, body: Buffer): Buffer {
  const key = Buffer.from(secret.replace(/^whsec_/, ""), "base64");
  return crypto.createHmac("sha256", key).update(`${id}.${ts}.`).update(body).digest();
}

export function verify(headers: Record<string, string | undefined>, body: Buffer, now = Date.now() / 1000) {
  const id = headers["webhook-id"], ts = headers["webhook-timestamp"], sigs = headers["webhook-signature"];
  if (!id || !ts || !sigs) throw new Error("missing webhook headers");
  if (!/^\d+$/.test(ts) || Math.abs(now - Number(ts)) > TOLERANCE_S) throw new Error("timestamp outside tolerance");
  const provided = sigs.split(" ").filter(s => s.startsWith("v1,")).map(s => Buffer.from(s.slice(3), "base64"));
  for (const secret of SECRETS) {
    const expected = sign(secret, id, ts, body);
    if (provided.some(p => p.length === expected.length && crypto.timingSafeEqual(p, expected))) return id;
  }
  throw new Error("no matching signature");
}

const app = express();
app.post("/webhook", express.raw({ type: "application/json" }), (req, res) => {
  let id: string;
  try { id = verify(req.headers as Record<string, string>, req.body as Buffer); }
  catch (e) { return res.status(401).send(String(e)); }
  if (seen.has(id)) return res.status(200).send("duplicate ignored");
  seen.add(id);
  const event = JSON.parse((req.body as Buffer).toString("utf8"));   // parse only AFTER verifying
  queueForProcessing(event);                                           // do slow work async
  res.status(200).send("ok");
});
declare function queueForProcessing(e: unknown): void;
